-- Fotos: Cera Mirras 150g e pinças laqueadas (contorno refeito em alta resolução)
INSERT INTO "stored_files" ("id","area","fileName","mimeType","sizeBytes","data","createdAt")
SELECT gen_random_uuid(),'products','della-cer-001-mi071.webp','image/webp',42930,decode('','hex'),now() WHERE NOT EXISTS (SELECT 1 FROM "stored_files" WHERE "fileName"='della-cer-001-mi071.webp');
DELETE FROM "product_images" i USING "products" p WHERE p."id"=i."productId" AND p."sku"='CER-001-MI071' AND i."fileName"<>'della-cer-001-mi071.webp';
INSERT INTO "product_images" ("id","productId","fileName","mimeType","isPrimary","sortOrder","createdAt")
SELECT gen_random_uuid(),p."id",'della-cer-001-mi071.webp','image/webp',true,0,now() FROM "products" p
 WHERE p."sku"='CER-001-MI071' AND NOT EXISTS (SELECT 1 FROM "product_images" i WHERE i."productId"=p."id");
